<template>
    <nav v-if="steps.length" class="wizard-navigation" :aria-label="label">
        <ol class="nav d-flex gap-0 p-0 m-0 flex-nowrap">
            <li v-for="(step, index) in steps" :key="step" class="nav-item flex-grow-1">
                <button
                    type="button"
                    class="nav-link wizard-step w-100"
                    :aria-current="index === activeStep ? 'step' : undefined"
                    @click="$emit('select', index)"
                >
                    {{ step }}
                </button>
            </li>
        </ol>
        <div class="moving-tab" :style="indicatorStyle" aria-hidden="true"></div>
    </nav>
</template>

<script>
export default {
    name: 'Stepper',
    props: {
        steps: { type: Array, required: true },
        activeStep: { type: Number, default: 0 },
        label: { type: String, default: 'Steps' },
    },
    emits: ['select'],
    computed: {
        indicatorStyle() {
            return {
                inlineSize: `${100 / this.steps.length}%`,
                transform: `translateX(${this.activeStep * 100}%)`,
            };
        },
    },
};
</script>

<style scoped>
.wizard-navigation {
    position: relative;
}

.wizard-navigation .nav {
    background: var(--bg-3);
}

.wizard-navigation .nav-item {
    flex-basis: 0;
    min-inline-size: 0;
}

.wizard-step {
    position: relative;
    z-index: 1;
    justify-content: center;
    border: 0;
    border-radius: 0;
    padding: .625rem .25rem;
    background: transparent;
    color: var(--fg-body);
    font-size: .75rem;
    font-weight: 500;
    text-transform: uppercase;
}

.wizard-step[aria-current='step'] {
    color: var(--primary-contrast, #fff);
}

.wizard-navigation .moving-tab {
    position: absolute;
    inset-block-start: -.375rem;
    inset-inline-start: 0;
    block-size: calc(100% + .75rem);
    border-radius: .25rem;
    background-color: var(--wizard-step-color, var(--primary-bg));
    pointer-events: none;
    transition: transform .25s ease;
}

@media (prefers-reduced-motion: reduce) {
    .wizard-navigation .moving-tab {
        transition: none;
    }
}
</style>
