<template>
    <div class="md:col-8 mx-auto">
        <Head title="Wizard" />

        <Card class="card-wizard active" data-color="rose">
            <template #start>
                <header class="wizard-header px-3">
                    <h3 class="card-title">Build Your Profile</h3>
                    <h5 class="card-description">This information will let us know more about you.</h5>
                </header>
                <Stepper :steps="steps" :active-step="activeStep" label="Profile setup" @select="goToStep" />
            </template>

            <form id="profile-wizard" novalidate class="tab-content" @submit.prevent="advance" @input="completed = false">
                <section v-show="activeStep === 0" ref="about">
                    <h5 class="info-text">Let’s start with the basic information</h5>
                    <div class="row justify-content-center">
                        <div class="sm:col-4">
                            <ImagePicker v-model="avatar" :placeholder="avatarPlaceholder" label="Choose Picture" class="wizard-picture" avatar />
                        </div>
                        <div class="sm:col-6">
                            <div v-for="field in nameFields" :key="field.name" class="d-flex align-items-center gap-3 mb-3">
                                <i class="material-icons" aria-hidden="true">{{ field.icon }}</i>
                                <div class="bmd-form-group flex-grow-1">
                                    <label :for="field.name" class="bmd-label-floating">{{ field.label }}</label>
                                    <input :id="field.name" type="text" class="form-control" :autocomplete="field.autocomplete" placeholder=" " minlength="3" required />
                                </div>
                            </div>
                        </div>
                        <div class="lg:col-10 mt-3">
                            <div class="d-flex align-items-center gap-3">
                                <i class="material-icons" aria-hidden="true">email</i>
                                <div class="bmd-form-group flex-grow-1">
                                    <label for="wizard-email" class="bmd-label-floating">Email (required)</label>
                                    <input id="wizard-email" type="email" class="form-control" autocomplete="email" placeholder=" " required />
                                </div>
                            </div>
                        </div>
                    </div>
                </section>

                <section v-show="activeStep === 1">
                    <h5 class="info-text">What are you doing?</h5>
                    <div class="row justify-content-center">
                        <div v-for="choice in choices" :key="choice.label" class="sm:col-4">
                            <button
                                type="button"
                                class="choice wizard-choice w-100"
                                :class="{ active: activities.includes(choice.label) }"
                                :aria-pressed="activities.includes(choice.label)"
                                @click="toggleChoice(choice.label)"
                            >
                                <span class="icon d-block"><i :class="`fa fa-${choice.icon}`" aria-hidden="true"></i></span>
                                <span class="h6">{{ choice.label }}</span>
                            </button>
                        </div>
                        <div class="sm:col-6 mt-3">
                            <Select42 v-model="accountCity" class="w-100" :options="cities" placeholder="Choose city" aria-label="Choose city" />
                        </div>
                    </div>
                </section>

                <section v-show="activeStep === 2">
                    <h5 class="info-text">Are you living in a nice area?</h5>
                    <div class="row justify-content-center gy-3">
                        <div class="sm:col-7">
                            <TextInputGroup name="wizard-street" label="Street Name" autocomplete="address-line1" />
                        </div>
                        <div class="sm:col-3">
                            <TextInputGroup name="wizard-street-number" label="Street No." autocomplete="address-line2" />
                        </div>
                        <div class="sm:col-5">
                            <TextInputGroup name="wizard-city" label="City" autocomplete="address-level2" />
                        </div>
                        <div class="sm:col-5">
                            <span id="wizard-country-label" class="d-block">Country</span>
                            <Select42 v-model="country" class="w-100" :options="countries" placeholder="Choose country" aria-labelledby="wizard-country-label" />
                        </div>
                    </div>
                    <p v-if="completed" class="fg-success text-center mt-3 mb-0" role="status">Demo profile completed.</p>
                </section>
            </form>

            <template #footer>
                <button v-if="activeStep > 0" type="button" class="btn" @click="goToStep(activeStep - 1)">Previous</button>
                <button type="submit" form="profile-wizard" class="btn btn-rose ms-auto">
                    {{ activeStep === steps.length - 1 ? 'Finish' : 'Next' }}
                </button>
            </template>
        </Card>
    </div>
</template>

<script>
import { Head } from '@inertiajs/vue3';
import Select42 from '@sulzanoks/select42';
import Card from '@scaffold/components/Card.vue';
import ImagePicker from '@scaffold/components/ImagePicker.vue';
import Stepper from '@scaffold/components/Stepper.vue';
import TextInputGroup from '@scaffold/components/TextInputGroup.vue';
import avatarPlaceholder from '@scaffold-assets/wizard-avatar.png';

export default {
    name: 'WizardDemo',
    components: { Card, Head, ImagePicker, Select42, Stepper, TextInputGroup },
    layout: { pageTitle: 'Wizard' },
    data() {
        return {
            steps: ['About', 'Account', 'Address'],
            activeStep: 0,
            completed: false,
            avatar: null,
            avatarPlaceholder,
            nameFields: [
                { name: 'wizard-first-name', label: 'First Name (required)', icon: 'face', autocomplete: 'given-name' },
                { name: 'wizard-last-name', label: 'Second Name (required)', icon: 'record_voice_over', autocomplete: 'family-name' },
            ],
            activities: [],
            choices: [
                { label: 'Design', icon: 'pencil' },
                { label: 'Code', icon: 'terminal' },
                { label: 'Develop', icon: 'laptop' },
            ],
            accountCity: null,
            cities: ['Riga', 'London', 'Rome'].map((text) => ({ value: text, text })),
            country: null,
            countries: ['Afghanistan', 'Albania', 'Algeria', 'American Samoa', 'Andorra', 'Angola', 'Anguilla', 'Antarctica', 'Latvia']
                .map((text) => ({ value: text, text })),
        };
    },
    methods: {
        validateAbout() {
            const invalidField = this.$refs.about.querySelector('input:invalid');
            if (!invalidField) {
                return true;
            }

            this.activeStep = 0;
            this.$nextTick(() => invalidField.reportValidity());
            return false;
        },
        goToStep(index) {
            if (index <= this.activeStep || this.validateAbout()) {
                this.activeStep = index;
                this.completed = false;
            }
        },
        advance() {
            if (this.activeStep < this.steps.length - 1) {
                this.goToStep(this.activeStep + 1);
            } else if (this.validateAbout()) {
                this.completed = true;
            }
        },
        toggleChoice(choice) {
            this.activities = this.activities.includes(choice)
                ? this.activities.filter((activity) => activity !== choice)
                : [...this.activities, choice];
        },
    },
};
</script>

<style scoped>
.wizard-picture :deep(img) {
    inline-size: 106px;
    border: 4px solid var(--border-color);
}

.wizard-choice {
    border: 0;
    padding: 0;
    background: transparent;
    color: inherit;
}
</style>
